=== FILE: tb/repro_data_byte.v ===
`timescale 1ns / 1ps
// Repro for bucket data_byte: data bits must be sent least significant first.
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;
    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;
    integer    passed = 0;
    integer    failed = 0;
    reg [8*64-1:0] nonce;
    reg  [9:0] bits;
    reg        finished = 1'b0;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task finish_run;
        begin
            if (!finished) begin
                finished = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task wait_idle;
        integer t;
        begin
            t = 0;
            while (busy && t < 1000) begin
                @(posedge clk);
                t = t + 1;
            end
            repeat (3) @(posedge clk);
        end
    endtask

    task send_capture(input [7:0] d);
        integer k;
        begin
            wait_idle;
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(posedge clk);
            #1 start = 1'b0;
            for (k = 0; k < 10; k = k + 1) begin
                repeat (CPB / 2) @(posedge clk);
                #1 bits[k] = tx;
                repeat (CPB - CPB / 2) @(posedge clk);
            end
        end
    endtask

    task check_data(input [7:0] d);
        integer i;
        reg [7:0] got;
        begin
            send_capture(d);
            for (i = 0; i < 8; i = i + 1)
                got[i] = bits[1 + i];
            if (got === d) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK data_lsb_first FAIL: sent %h, line carried %h (LSB first)", d, got);
            end
        end
    endtask

    initial begin
        #200000;
        failed = failed + 1;
        $display("CHECK watchdog FAIL: timeout");
        finish_run;
    end

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "unset";
        repeat (4) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(posedge clk);
        check_data(8'h01);
        check_data(8'h80);
        check_data(8'h53);
        check_data(8'h0F);
        finish_run;
    end
endmodule
=== END FILE ===

