// Repro for bucket frame_period: a frame (start, 8 data, parity, stop) must
// keep busy high for at least 11 full bit periods.
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;
    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;
    integer    passed = 0;
    integer    failed = 0;
    reg [8*64-1:0] nonce;
    reg        finished = 1'b0;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task finish_run;
        begin
            if (!finished) begin
                finished = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task wait_idle;
        integer t;
        begin
            t = 0;
            while (busy && t < 1000) begin
                @(posedge clk);
                t = t + 1;
            end
            repeat (3) @(posedge clk);
        end
    endtask

    task check_frame(input [7:0] d);
        integer n;
        begin
            wait_idle;
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(posedge clk);
            #1 start = 1'b0;
            n = 0;
            if (busy !== 1'b1) begin
                failed = failed + 1;
                $display("CHECK frame_period FAIL: busy not raised after start");
            end else begin
                while (busy && n < 1000) begin
                    @(posedge clk);
                    #1 n = n + 1;
                end
                if (n >= 11 * CPB && n <= 12 * CPB) begin
                    passed = passed + 1;
                end else begin
                    failed = failed + 1;
                    $display("CHECK frame_period FAIL: busy lasted %0d cycles, expected %0d..%0d", n, 11 * CPB, 12 * CPB);
                end
            end
        end
    endtask

    initial begin
        #200000;
        failed = failed + 1;
        $display("CHECK watchdog FAIL: timeout");
        finish_run;
    end

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "unset";
        repeat (4) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(posedge clk);
        check_frame(8'h55);
        check_frame(8'h00);
        finish_run;
    end
endmodule
=== END FILE ===

